<?php
require_once __DIR__.'/Caja.php';
require_once __DIR__.'/Producto.php';
class CuentaPagar
{
    private $db;
    public function __construct(PDO $db){$this->db=$db;}
    private function query($sql,array $args=array()){$q=$this->db->prepare($sql);$q->execute($args);return $q->fetchAll();}
    public static function saldoSql($alias='c'){return '('.$alias.'.saldo_base-COALESCE((SELECT SUM(p.monto) FROM pagos_proveedor p WHERE p.compra_id='.$alias.'.id),0))';}
    private function hoy(){return (new DateTimeImmutable('now',new DateTimeZone('America/Mexico_City')))->format('Y-m-d');}
    private function actor($id,$permiso){$this->db->query('SELECT id FROM roles ORDER BY id FOR SHARE')->fetchAll();$q=$this->db->prepare('SELECT id FROM usuarios WHERE id=? FOR UPDATE');$q->execute(array($id));$q->fetchColumn();$a=(new Usuario($this->db))->buscar($id);if(!$a||!$a['activo']||(empty($a['permisos']['todo'])&&(empty($a['permisos'][$permiso])||empty($a['permisos']['ver_cuentas_pagar']))))throw new HttpError('No tienes permiso para esta operación.',403);return $a;}
    public function listar(array $f){
        $where="c.estatus='recibida'";$args=array();$s=Producto::texto($f,'buscar',100,false);if($s!==''){$like='%'.str_replace(array('!','%','_'),array('!!','!%','!_'),$s).'%';$where.=" AND (c.folio LIKE ? ESCAPE '!' OR pr.nombre LIKE ? ESCAPE '!' OR c.factura_proveedor LIKE ? ESCAPE '!')";array_push($args,$like,$like,$like);}
        $prov=Producto::identificador(isset($f['proveedor_id'])&&$f['proveedor_id']!==''?$f['proveedor_id']:null,true);if($prov!==null){$where.=' AND c.proveedor_id=?';$args[]=$prov;}
        $estado=isset($f['estado'])?$f['estado']:'pendiente';$saldo=self::saldoSql();if(!in_array($estado,array('pendiente','pagada','por_conciliar','vencida','todos'),true))throw new HttpError('Selecciona un estado válido.');if($estado==='pendiente')$where.=' AND '.$saldo.'>0';if($estado==='pagada')$where.=' AND c.saldo_base IS NOT NULL AND '.$saldo.'=0';if($estado==='por_conciliar')$where.=' AND c.saldo_base IS NULL';if($estado==='vencida'){$where.=' AND '.$saldo.'>0 AND c.vence<?';$args[]=$this->hoy();}
        $base=' FROM compras c JOIN proveedores pr ON pr.id=c.proveedor_id WHERE '.$where;$this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{
            $summary=$this->query('SELECT COUNT(*) compras,SUM(c.saldo_base IS NULL) por_conciliar,CAST(COALESCE(SUM('.$saldo.'),0) AS DECIMAL(24,2)) saldo'.$base,$args)[0];
            $vendors=$this->query('SELECT c.proveedor_id,MAX(pr.nombre) nombre,COUNT(*) compras,SUM(c.saldo_base IS NULL) por_conciliar,CAST(COALESCE(SUM('.$saldo.'),0) AS DECIMAL(24,2)) saldo'.$base.' GROUP BY c.proveedor_id ORDER BY saldo DESC,c.proveedor_id',$args);
            if(isset($f['antes_de'])&&$f['antes_de']!==''){$base.=' AND c.id<?';$args[]=Producto::identificador($f['antes_de']);}
            $rows=$this->query('SELECT c.id,c.folio,c.proveedor_id,pr.nombre proveedor,c.total,c.condicion_pago,c.vence,c.saldo_base,CAST('.$saldo.' AS DECIMAL(14,2)) saldo,c.factura_proveedor'.$base.' ORDER BY c.id DESC LIMIT 31',$args);$more=count($rows)>30;if($more)array_pop($rows);$this->db->commit();return array('resumen'=>$summary,'proveedores'=>$vendors,'compras'=>$rows,'siguiente'=>$more?$rows[count($rows)-1]['id']:null,'hoy'=>$this->hoy());
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function catalogos(){return $this->query("SELECT DISTINCT p.id,p.nombre,p.activo FROM proveedores p JOIN compras c ON c.proveedor_id=p.id WHERE c.estatus='recibida' ORDER BY p.nombre,p.id");}
    private function compra($id,$lock=false){$rows=$this->query('SELECT c.*,pr.nombre proveedor FROM compras c JOIN proveedores pr ON pr.id=c.proveedor_id WHERE c.id=?'.($lock?' FOR UPDATE':''),array($id));if(!$rows)throw new HttpError('Compra no encontrada.',404);$c=$rows[0];if($c['estatus']!=='recibida')throw new HttpError('Las cuentas por pagar corresponden a compras recibidas.',409);$c['version']=hash('sha256',json_encode(array($c['id'],$c['total'],$c['saldo_base'],$c['condicion_pago'],$c['vence'],$c['conciliacion'])));return $c;}
    public function obtener($id,array $actor){
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{$c=$this->compra($id);$q=$this->db->prepare('SELECT CAST('.self::saldoSql().' AS DECIMAL(14,2)) FROM compras c WHERE c.id=?');$q->execute(array($id));$saldo=$q->fetchColumn();
            $r=array('id'=>$c['id'],'folio'=>$c['folio'],'proveedor'=>$c['proveedor'],'proveedor_id'=>$c['proveedor_id'],'factura'=>$c['factura_proveedor'],'total'=>$c['total'],'condicion_pago'=>$c['condicion_pago'],'vence'=>$c['vence'],'saldo_base'=>$c['saldo_base'],'saldo'=>$saldo,'version'=>$c['version'],'conciliacion'=>$c['conciliacion']?json_decode($c['conciliacion'],true):null,'pagos'=>$this->query('SELECT id,folio,monto,origen,cuenta,referencia,notas,datos,UNIX_TIMESTAMP(creado_en) creado_unix FROM pagos_proveedor WHERE compra_id=? ORDER BY id DESC',array($id)));
            foreach($r['pagos'] as &$p){$p['datos']=json_decode($p['datos'],true);}unset($p);$r['metodos']=$this->db->query("SELECT id,nombre,tipo FROM metodos_pago WHERE activo=1 AND tipo<>'credito' ORDER BY id")->fetchAll();$r['turnos']=$this->query("SELECT t.id,c.nombre caja FROM turnos_caja t JOIN cajas c ON c.id=t.caja_id JOIN ubicaciones l ON l.id=COALESCE(t.ubicacion_id,c.ubicacion_id) WHERE t.abierto_por=? AND t.estatus='abierto' AND c.activo=1 AND l.activo=1 AND l.disponible_venta=1",array($actor['id']));$r['puede_pagar']=!empty($actor['permisos']['todo'])||!empty($actor['permisos']['pagar_proveedores']);$r['puede_caja']=!empty($actor['permisos']['todo'])||!empty($actor['permisos']['operar_caja']);$r['puede_conciliar']=!empty($actor['permisos']['todo']);$this->db->commit();return $r;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function conciliar($id,array $d,$actorId){
        $n=Caja::centavos(isset($d['saldo_inicial'])?$d['saldo_inicial']:null);$notes=Producto::texto($d,'motivo',300,true);$condition=isset($d['condicion_pago'])?$d['condicion_pago']:null;if(!in_array($condition,array('contado','credito'),true))throw new HttpError('Selecciona contado o crédito.');$due=isset($d['vence'])&&$d['vence']!==''?$d['vence']:null;if($condition==='contado')$due=$this->hoy();if($due!==null){$date=is_string($due)?DateTimeImmutable::createFromFormat('!Y-m-d',$due):false;if(!$date||$date->format('Y-m-d')!==$due||$due<'2023-01-01'||$due>'9998-12-31')throw new HttpError('Selecciona un vencimiento válido.');}if($n&&$condition==='credito'&&$due===null)throw new HttpError('Indica el vencimiento del saldo a crédito.');
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{$a=$this->actor($actorId,'todo');$c=$this->compra($id,true);if($c['saldo_base']!==null)throw new HttpError('El saldo inicial ya fue confirmado y no se puede volver a conciliar.',409);if(!isset($d['version'])||!is_string($d['version'])||!hash_equals($c['version'],$d['version']))throw new HttpError('La compra cambió. Vuelve a consultarla.',409);if($n>Caja::centavos($c['total']))throw new HttpError('El saldo confirmado no puede superar el total de la compra.');$audit=array('usuario_id'=>$actorId,'usuario'=>$a['nombre'],'motivo'=>$notes,'pagado_previamente'=>Caja::dinero(Caja::centavos($c['total'])-$n),'fecha'=>(new DateTimeImmutable('now',new DateTimeZone('America/Mexico_City')))->format('Y-m-d H:i:s'));
            $this->db->prepare('UPDATE compras SET condicion_pago=?,vence=?,saldo_base=?,conciliacion=? WHERE id=?')->execute(array($condition,$due,Caja::dinero($n),json_encode($audit),$id));$this->db->commit();return array('compra_id'=>$id);
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function pagar($id,array $d,$actorId){
        $origin=isset($d['origen'])?$d['origen']:null;if(!in_array($origin,array('caja','externo'),true))throw new HttpError('Indica de dónde sale el dinero.');$turn=$origin==='caja'?Producto::identificador(isset($d['turno_id'])?$d['turno_id']:null):null;$method=Producto::identificador(isset($d['metodo_pago_id'])?$d['metodo_pago_id']:null);$n=Caja::centavos(isset($d['monto'])?$d['monto']:null);if(!$n)throw new HttpError('El pago debe ser mayor que cero.');$account=$origin==='externo'?Producto::texto($d,'cuenta',100,true):null;$ref=Producto::texto($d,'referencia',100,false);$notes=Producto::texto($d,'notas',300,true);$key=isset($d['clave'])?$d['clave']:'';if(!is_string($key)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/D',$key))throw new HttpError('Recarga el formulario del pago.');$hash=hash('sha256',json_encode(array((string)$id,$origin,$turn,$method,$n,$account,$ref,$notes)));
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{$actor=$this->actor($actorId,'pagar_proveedores');$q=$this->db->prepare('SELECT id,folio,huella,monto FROM pagos_proveedor WHERE usuario_id=? AND clave=?');$q->execute(array($actorId,$key));$old=$q->fetch();if($old){if(!hash_equals($old['huella'],$hash))throw new HttpError('La solicitud ya se utilizó con otros datos.',409);$this->db->commit();return array('pago_id'=>$old['id'],'folio'=>$old['folio'],'monto'=>$old['monto']);}
            $t=null;if($origin==='caja'){
                if(empty($actor['permisos']['todo'])&&empty($actor['permisos']['operar_caja']))throw new HttpError('Necesitas permiso para operar caja.',403);$q=$this->db->prepare('SELECT caja_id FROM turnos_caja WHERE id=?');$q->execute(array($turn));$box=$q->fetchColumn();if(!$box)throw new HttpError('Turno no encontrado.',404);$q=$this->db->prepare('SELECT id FROM cajas WHERE id=? FOR UPDATE');$q->execute(array($box));$q->fetchColumn();$q=$this->db->prepare('SELECT * FROM turnos_caja WHERE id=? FOR UPDATE');$q->execute(array($turn));$t=$q->fetch();if($t['estatus']!=='abierto'||(string)$t['abierto_por']!==(string)$actorId)throw new HttpError('El pago debe salir de tu propio turno abierto.',403);
                $rows=$this->query('SELECT c.nombre caja,c.activo,l.activo ubicacion_activa,l.disponible_venta FROM cajas c JOIN ubicaciones l ON l.id=COALESCE(?,c.ubicacion_id) WHERE c.id=?',array($t['ubicacion_id'],$box));$b=$rows[0];if(!$b['activo']||!$b['ubicacion_activa']||!$b['disponible_venta'])throw new HttpError('La caja y su ubicación deben estar habilitadas.',409);$t['caja_nombre']=$b['caja'];
            }
            $c=$this->compra($id,true);if($c['saldo_base']===null)throw new HttpError('El administrador debe confirmar primero el saldo inicial de esta compra.',409);$q=$this->db->prepare('SELECT '.self::saldoSql().' FROM compras c WHERE c.id=?');$q->execute(array($id));$pending=Caja::centavos($q->fetchColumn());if($n>$pending)throw new HttpError('El pago supera el saldo pendiente. Actualiza la cuenta.',409);
            $q=$this->db->prepare('SELECT id,nombre,tipo,activo FROM metodos_pago WHERE id=? FOR SHARE');$q->execute(array($method));$m=$q->fetch();if(!$m||!$m['activo']||$m['tipo']==='credito')throw new HttpError('Selecciona un método activo distinto de crédito.');if($origin==='caja'&&$m['tipo']!=='efectivo')throw new HttpError('La caja solo entrega efectivo. Usa fondos externos para otro método.');if($origin==='caja'){$cash=(new Caja($this->db))->resumenBloqueado($t);if($n>max(0,Caja::centavos($cash['esperado'],true)))throw new HttpError('No hay efectivo suficiente en la caja.',409);}
            $data=array('usuario'=>$actor['nombre'],'proveedor'=>$c['proveedor'],'compra_folio'=>$c['folio'],'factura'=>$c['factura_proveedor'],'metodo'=>$m['nombre'],'caja'=>$t?$t['caja_nombre']:null);
            $this->db->prepare('INSERT INTO pagos_proveedor(folio,compra_id,proveedor_id,usuario_id,turno_id,metodo_pago_id,tipo_metodo,origen,cuenta,monto,referencia,notas,clave,huella,datos) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute(array('P-'.bin2hex(random_bytes(10)),$id,$c['proveedor_id'],$actorId,$turn,$method,$m['tipo'],$origin,$account,Caja::dinero($n),$ref,$notes,$key,$hash,json_encode($data)));$p=$this->db->lastInsertId();$folio='PP-'.str_pad($p,8,'0',STR_PAD_LEFT);$this->db->prepare('UPDATE pagos_proveedor SET folio=? WHERE id=?')->execute(array($folio,$p));$this->db->commit();return array('pago_id'=>$p,'folio'=>$folio,'monto'=>Caja::dinero($n));
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
